export type StringKey = keyof (typeof strings)['ar'];
export const t = (lang: Lang, key: StringKey): string => strings[lang][key];

const STAGE_ICON: Record<string, string> = { new: '🆕', contacted: '📞', interested: '👍', viewing: '🏠', negotiation: '🤝', won: '✅', lost: '❌' };
/** A lead stage with its icon, worded the same as the website. */
export const stageLabel = (lang: Lang, stage: string): string => `${STAGE_ICON[stage] ?? ''} ${t(lang, `st_${stage}` as StringKey)}`.trim();
